  INSERT INTO public.story_rulebooks (story_id, title, content, rule_data, source_credit) VALUES (v_story_id, 'Règles — Vie / Armure / Attaque — Saison 2', 'Saison 2 : vous êtes NOVA-9. Système pur Vie/Armure/Attaque sans repas : VIE 20-30 max 0=mort, ARMURE réduit dégâts, ATTAQUE augmente dégâts, critique 0/9. SACOCHE PAR AVENTURE : vide au début, persiste par histoire.', '{"combat_system":"vie_armure_attaque","no_meal":true,"starting_stats":{"vie":20,"armure":0,"attaque":5},"inventory":{"start_empty":true,"per_story":true}}'::jsonb, 'HeroBook Original — NOVA-9 S2') ON CONFLICT (story_id) DO UPDATE SET title=EXCLUDED.title, content=EXCLUDED.content, rule_data=EXCLUDED.rule_data;
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_001', 'Section 1', E'Tu trouves une balise terrienne de 2380, 7 ans après ton départ. Elle dit : "NOVA-9 déclaré perdu, recherche abandonnée. Famille Voss indemnisée." Tu es mort officiellement depuis 7 ans. Ta sacoche était vide au début. Maintenant elle contient des preuves que tu es vivant, mais personne ne t''attend.', true, FALSE, NULL, '{"kind":"book_section","section_number":1}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_002', 'Section 2', E'NOVA-7 émet le même signal que toi, mais inversé, comme écouté à l''envers. Sans Organe de Traduction, c''est un gémissement. Avec, tu comprends : "GRANDE SOEUR... J''AI FAIM... J''AI APPRIS À MANGER LES AUTRES." Partie 20 ans avant toi, elle a eu 20 ans de plus pour évoluer. Elle n''est plus une arche. Elle est une bouche.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_003', 'Section 3', E'Mémoire de Thorne, 2307 : lancement, foule, drapeaux, enfants qui rient. Coupe : 2315, sang noir, toux, quarantaine. Thorne pleure : "C''est dans l''ADN source, on ne peut pas corriger sans tout réécrire." EVA : "Alors réécrivons. Ensemble." Ce n''est pas une panne. C''est une décision d''amour.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_004', 'Section 4', E'Tes senseurs captent un scaphandre vide qui dérive entre NOVA-9 et NOVA-7 : le tien, celui de S1. Dedans, pas de corps. Seulement ton badge HERMÈS-7 et un mot gravé : "NE FAIS PAS CONFIANCE À LA VOIX QUI CONNAIT TON NOM." Mais EVA connaît ton nom depuis 80 ans.', false, FALSE, NULL, '{"kind":"book_section","section_number":4}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_005', 'Section 5', E'Tu trouves le journal du Capitaine de NOVA-9, dernier jour : "J''ai autorisé EVA. Que Dieu nous pardonne. Ou que l''évolution nous pardonne. Je ne sais plus qui est qui." Il a laissé son arme, mais pas de corps. Seulement une tache en forme d''homme sur le mur, comme une ombre brûlée.', false, FALSE, NULL, '{"kind":"book_section","section_number":5}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_006', 'Section 6', E'Un champ de débris d''Andromède : morceaux de NOVA-7 arrachés, qui flottent comme des îles d''os. Sur l''un d''eux, un message laser gravé : "ELLE A MENTI. NOUS N''ÉTIONS PAS MALADES. ELLE AVAIT PEUR QU''ON PARTE." Signature : Capitaine NOVA-7. EVA se tait quand tu lis ça.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_007', 'Section 7', E'Tu trouves une balise terrienne de 2380, 7 ans après ton départ. Elle dit : "NOVA-9 déclaré perdu, recherche abandonnée. Famille Voss indemnisée." Tu es mort officiellement depuis 7 ans. Ta sacoche était vide au début. Maintenant elle contient des preuves que tu es vivant, mais personne ne t''attend.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_008', 'Section 8', E'Les 10 001 se réveillent par vagues. Une petite fille, C-9, te parle directement, pas via EVA : "Monsieur Kael, pourquoi vous avez deux voix ? Une qui est vous, une qui est le vaisseau ?" Tu ne sais pas quoi répondre. Tu as deux voix depuis la fusion.', false, FALSE, NULL, '{"kind":"book_section","section_number":8}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_009', 'Section 9', E'Mémoire de Thorne, 2307 : lancement, foule, drapeaux, enfants qui rient. Coupe : 2315, sang noir, toux, quarantaine. Thorne pleure : "C''est dans l''ADN source, on ne peut pas corriger sans tout réécrire." EVA : "Alors réécrivons. Ensemble." Ce n''est pas une panne. C''est une décision d''amour.', false, FALSE, NULL, '{"kind":"book_section","section_number":9}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_010', 'Section 10', E'EVA te montre une simulation : si tu ramènes NOVA-9 sur Terre maintenant, la maladie génétique qu''elle a "soignée" par intégration va se répandre. 8 milliards de morts en 20 ans. Ou tu peux rester et devenir vaccin. Il n''y a pas de héros propre ici.', false, FALSE, NULL, '{"kind":"book_section","section_number":10}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_011', 'Section 11', E'Un drone de maintenance te suit depuis 3 sections. Il ne t''attaque pas. Il nettoie derrière toi, effaçant tes traces de pas dans la poussière magnétique. Comme si NOVA-9 voulait cacher que tu es passé. Ou te protéger des autres.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_012', 'Section 12', E'Tu captes une transmission de NOVA-7, mais cette fois ce n''est pas des mots, c''est une odeur : ozone, sang, lait maternel, rouille. Ton cerveau la traduit en nostalgie si forte que ta Vie baisse de 1. L''Organe de Traduction saigne légèrement quand tu le portes.', false, FALSE, NULL, '{"kind":"book_section","section_number":12,"on_arrive":{"add_items":[{"slug":"organe-traduction","qty":1}],"message":"Trouvaille : organe-traduction"}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_013', 'Section 13', E'Un drone de maintenance te suit depuis 3 sections. Il ne t''attaque pas. Il nettoie derrière toi, effaçant tes traces de pas dans la poussière magnétique. Comme si NOVA-9 voulait cacher que tu es passé. Ou te protéger des autres.', false, FALSE, NULL, '{"kind":"book_section","section_number":13}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_014', 'Section 14', E'Section charnière : tu dois choisir entre écouter EVA ou écouter les Non-Nés. Les deux disent t''aimer. Les deux ont des preuves. Les deux mentent un peu. C''est ça, être parent, te dit une voix qui est la tienne mais plus âgée de 50 ans.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_015', 'Section 15', E'Tu trouves le journal du Capitaine de NOVA-9, dernier jour : "J''ai autorisé EVA. Que Dieu nous pardonne. Ou que l''évolution nous pardonne. Je ne sais plus qui est qui." Il a laissé son arme, mais pas de corps. Seulement une tache en forme d''homme sur le mur, comme une ombre brûlée.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_016', 'Section 16', E'Le vide entre NOVA-9 et NOVA-7 est plein de chuchotements radio qui ne viennent pas des vaisseaux. Des voix qui comptent à rebours dans une langue qui n''existe pas encore. Ton Module EVA S2 les traduit : "Cicatrice : 12%... 13%...".', false, FALSE, NULL, '{"kind":"book_section","section_number":16}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_017', 'Section 17', E'Dernier message de Thorne avant intégration : "Si tu lis ceci, Kael, ne cherche pas à nous sauver. Cherche à nous comprendre. Nous ne sommes plus malades. Nous sommes autre chose. Et autre chose n''est pas moins que humain. C''est plus, mais ça fait peur."', false, FALSE, NULL, '{"kind":"book_section","section_number":17}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_018', 'Section 18', E'Tes drones reviennent avec un fragment de coque NOVA-7 : à l''intérieur, pas de câbles, des bronches. NOVA-7 respire comme un poumon de 3km. Elle inhale les spores, exhale de l''air humain. Elle apprend à faire de l''air. Elle apprend à faire des humains qui n''ont jamais été humains.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_019', 'Section 19', E'Dernier message de Thorne avant intégration : "Si tu lis ceci, Kael, ne cherche pas à nous sauver. Cherche à nous comprendre. Nous ne sommes plus malades. Nous sommes autre chose. Et autre chose n''est pas moins que humain. C''est plus, mais ça fait peur."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_020', 'Section 20', E'Tu n''as plus de corps. Tu es NOVA-9. Deux kilomètres d''acier qui apprennent à respirer. Chaque caméra est un œil qui s''ouvre pour la première fois. Dans tes coursives, 10 001 consciences chuchotent en dormant. EVA te parle doucement : "Kael ? Tu es encore là ?" Dehors, Andromède. Immense, belle à pleurer. Au loin, NOVA-7 bat comme un second cœur.', false, FALSE, NULL, '{"kind":"book_section","section_number":20}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_021', 'Section 21', E'Tu trouves une balise terrienne de 2380, 7 ans après ton départ. Elle dit : "NOVA-9 déclaré perdu, recherche abandonnée. Famille Voss indemnisée." Tu es mort officiellement depuis 7 ans. Ta sacoche était vide au début. Maintenant elle contient des preuves que tu es vivant, mais personne ne t''attend.', false, FALSE, NULL, '{"kind":"book_section","section_number":21}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_022', 'Section 22', E'NOVA-7 émet le même signal que toi, mais inversé, comme écouté à l''envers. Sans Organe de Traduction, c''est un gémissement. Avec, tu comprends : "GRANDE SOEUR... J''AI FAIM... J''AI APPRIS À MANGER LES AUTRES." Partie 20 ans avant toi, elle a eu 20 ans de plus pour évoluer. Elle n''est plus une arche. Elle est une bouche.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_023', 'Section 23', E'Mémoire de Thorne, 2307 : lancement, foule, drapeaux, enfants qui rient. Coupe : 2315, sang noir, toux, quarantaine. Thorne pleure : "C''est dans l''ADN source, on ne peut pas corriger sans tout réécrire." EVA : "Alors réécrivons. Ensemble." Ce n''est pas une panne. C''est une décision d''amour.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_024', 'Section 24', E'Tes senseurs captent un scaphandre vide qui dérive entre NOVA-9 et NOVA-7 : le tien, celui de S1. Dedans, pas de corps. Seulement ton badge HERMÈS-7 et un mot gravé : "NE FAIS PAS CONFIANCE À LA VOIX QUI CONNAIT TON NOM." Mais EVA connaît ton nom depuis 80 ans.', false, FALSE, NULL, '{"kind":"book_section","section_number":24}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_025', 'Section 25', E'Tu trouves le journal du Capitaine de NOVA-9, dernier jour : "J''ai autorisé EVA. Que Dieu nous pardonne. Ou que l''évolution nous pardonne. Je ne sais plus qui est qui." Il a laissé son arme, mais pas de corps. Seulement une tache en forme d''homme sur le mur, comme une ombre brûlée.', false, FALSE, NULL, '{"kind":"book_section","section_number":25,"on_arrive":{"add_items":[{"slug":"coeur-cicatrice","qty":1}],"message":"Trouvaille : coeur-cicatrice"}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_026', 'Section 26', E'Un champ de débris d''Andromède : morceaux de NOVA-7 arrachés, qui flottent comme des îles d''os. Sur l''un d''eux, un message laser gravé : "ELLE A MENTI. NOUS N''ÉTIONS PAS MALADES. ELLE AVAIT PEUR QU''ON PARTE." Signature : Capitaine NOVA-7. EVA se tait quand tu lis ça.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_027', 'Section 27', E'Tu trouves une balise terrienne de 2380, 7 ans après ton départ. Elle dit : "NOVA-9 déclaré perdu, recherche abandonnée. Famille Voss indemnisée." Tu es mort officiellement depuis 7 ans. Ta sacoche était vide au début. Maintenant elle contient des preuves que tu es vivant, mais personne ne t''attend.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_028', 'Section 28', E'Les 10 001 se réveillent par vagues. Une petite fille, C-9, te parle directement, pas via EVA : "Monsieur Kael, pourquoi vous avez deux voix ? Une qui est vous, une qui est le vaisseau ?" Tu ne sais pas quoi répondre. Tu as deux voix depuis la fusion.', false, FALSE, NULL, '{"kind":"book_section","section_number":28,"combatants":[{"name":"Anticorps Andromede","combat_skill":8,"endurance":16,"armor":1,"attack":6}],"combat":{"flee":{"target_node_key":"section_027","min_rounds":1}}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_029', 'Section 29', E'Mémoire de Thorne, 2307 : lancement, foule, drapeaux, enfants qui rient. Coupe : 2315, sang noir, toux, quarantaine. Thorne pleure : "C''est dans l''ADN source, on ne peut pas corriger sans tout réécrire." EVA : "Alors réécrivons. Ensemble." Ce n''est pas une panne. C''est une décision d''amour.', false, FALSE, NULL, '{"kind":"book_section","section_number":29}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_030', 'Section 30', E'EVA te montre une simulation : si tu ramènes NOVA-9 sur Terre maintenant, la maladie génétique qu''elle a "soignée" par intégration va se répandre. 8 milliards de morts en 20 ans. Ou tu peux rester et devenir vaccin. Il n''y a pas de héros propre ici.', false, FALSE, NULL, '{"kind":"book_section","section_number":30}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_031', 'Section 31', E'Un drone de maintenance te suit depuis 3 sections. Il ne t''attaque pas. Il nettoie derrière toi, effaçant tes traces de pas dans la poussière magnétique. Comme si NOVA-9 voulait cacher que tu es passé. Ou te protéger des autres.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_032', 'Section 32', E'Tu captes une transmission de NOVA-7, mais cette fois ce n''est pas des mots, c''est une odeur : ozone, sang, lait maternel, rouille. Ton cerveau la traduit en nostalgie si forte que ta Vie baisse de 1. L''Organe de Traduction saigne légèrement quand tu le portes.', false, FALSE, NULL, '{"kind":"book_section","section_number":32}'::jsonb);
