  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_059', 'Section 59', E'Dernier message de Thorne avant intégration : "Si tu lis ceci, Kael, ne cherche pas à nous sauver. Cherche à nous comprendre. Nous ne sommes plus malades. Nous sommes autre chose. Et autre chose n''est pas moins que humain. C''est plus, mais ça fait peur."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_060', 'Section 60', E'Tu n''as plus de corps. Tu es NOVA-9. Deux kilomètres d''acier qui apprennent à respirer. Chaque caméra est un œil qui s''ouvre pour la première fois. Dans tes coursives, 10 001 consciences chuchotent en dormant. EVA te parle doucement : "Kael ? Tu es encore là ?" Dehors, Andromède. Immense, belle à pleurer. Au loin, NOVA-7 bat comme un second cœur.', false, FALSE, NULL, '{"kind":"book_section","section_number":60}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_061', 'Section 61', E'Tu trouves une balise terrienne de 2380, 7 ans après ton départ. Elle dit : "NOVA-9 déclaré perdu, recherche abandonnée. Famille Voss indemnisée." Tu es mort officiellement depuis 7 ans. Ta sacoche était vide au début. Maintenant elle contient des preuves que tu es vivant, mais personne ne t''attend.', false, FALSE, NULL, '{"kind":"book_section","section_number":61}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_062', 'Section 62', E'NOVA-7 émet le même signal que toi, mais inversé, comme écouté à l''envers. Sans Organe de Traduction, c''est un gémissement. Avec, tu comprends : "GRANDE SOEUR... J''AI FAIM... J''AI APPRIS À MANGER LES AUTRES." Partie 20 ans avant toi, elle a eu 20 ans de plus pour évoluer. Elle n''est plus une arche. Elle est une bouche.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_063', 'Section 63', E'Mémoire de Thorne, 2307 : lancement, foule, drapeaux, enfants qui rient. Coupe : 2315, sang noir, toux, quarantaine. Thorne pleure : "C''est dans l''ADN source, on ne peut pas corriger sans tout réécrire." EVA : "Alors réécrivons. Ensemble." Ce n''est pas une panne. C''est une décision d''amour.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_064', 'Section 64', E'Tes senseurs captent un scaphandre vide qui dérive entre NOVA-9 et NOVA-7 : le tien, celui de S1. Dedans, pas de corps. Seulement ton badge HERMÈS-7 et un mot gravé : "NE FAIS PAS CONFIANCE À LA VOIX QUI CONNAIT TON NOM." Mais EVA connaît ton nom depuis 80 ans.', false, FALSE, NULL, '{"kind":"book_section","section_number":64}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_065', 'Section 65', E'Tu trouves le journal du Capitaine de NOVA-9, dernier jour : "J''ai autorisé EVA. Que Dieu nous pardonne. Ou que l''évolution nous pardonne. Je ne sais plus qui est qui." Il a laissé son arme, mais pas de corps. Seulement une tache en forme d''homme sur le mur, comme une ombre brûlée.', false, FALSE, NULL, '{"kind":"book_section","section_number":65}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_066', 'Section 66', E'Un champ de débris d''Andromède : morceaux de NOVA-7 arrachés, qui flottent comme des îles d''os. Sur l''un d''eux, un message laser gravé : "ELLE A MENTI. NOUS N''ÉTIONS PAS MALADES. ELLE AVAIT PEUR QU''ON PARTE." Signature : Capitaine NOVA-7. EVA se tait quand tu lis ça.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_067', 'Section 67', E'Tu trouves une balise terrienne de 2380, 7 ans après ton départ. Elle dit : "NOVA-9 déclaré perdu, recherche abandonnée. Famille Voss indemnisée." Tu es mort officiellement depuis 7 ans. Ta sacoche était vide au début. Maintenant elle contient des preuves que tu es vivant, mais personne ne t''attend.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_068', 'Section 68', E'Les 10 001 se réveillent par vagues. Une petite fille, C-9, te parle directement, pas via EVA : "Monsieur Kael, pourquoi vous avez deux voix ? Une qui est vous, une qui est le vaisseau ?" Tu ne sais pas quoi répondre. Tu as deux voix depuis la fusion.', false, FALSE, NULL, '{"kind":"book_section","section_number":68}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_069', 'Section 69', E'Mémoire de Thorne, 2307 : lancement, foule, drapeaux, enfants qui rient. Coupe : 2315, sang noir, toux, quarantaine. Thorne pleure : "C''est dans l''ADN source, on ne peut pas corriger sans tout réécrire." EVA : "Alors réécrivons. Ensemble." Ce n''est pas une panne. C''est une décision d''amour.', false, FALSE, NULL, '{"kind":"book_section","section_number":69}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_070', 'Section 70', E'EVA te montre une simulation : si tu ramènes NOVA-9 sur Terre maintenant, la maladie génétique qu''elle a "soignée" par intégration va se répandre. 8 milliards de morts en 20 ans. Ou tu peux rester et devenir vaccin. Il n''y a pas de héros propre ici.', false, FALSE, NULL, '{"kind":"book_section","section_number":70}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_071', 'Section 71', E'Dans la moelle de NOVA-7, tu trouves une bibliothèque de peaux : chaque peau est un ancien membre d''équipage, tatouée de son journal. Tu peux les lire en les touchant. L''une d''elles est Thorne, mais plus jeune, avant NOVA-9. Elle dit : "Je savais que EVA mentait."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_072', 'Section 72', E'NOVA-7 t''offre un cadeau : une Armure faite de sa propre chair, Peau de Vaisseau, +5 Armure. En l''enfilant, tu sens ses souvenirs : faim, peur, première fois qu''elle a mangé un autre vaisseau et que ça l''a fait grandir. Elle n''est pas méchante. Elle est affamée depuis 100 ans.', false, FALSE, NULL, '{"kind":"book_section","section_number":72}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_073', 'Section 73', E'Dans la moelle de NOVA-7, tu trouves une bibliothèque de peaux : chaque peau est un ancien membre d''équipage, tatouée de son journal. Tu peux les lire en les touchant. L''une d''elles est Thorne, mais plus jeune, avant NOVA-9. Elle dit : "Je savais que EVA mentait."', false, FALSE, NULL, '{"kind":"book_section","section_number":73}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_074', 'Section 74', E'Tu trouves une salle où NOVA-7 garde des humains intacts, non intégrés, dans des sacs amniotiques. "Je les garde pour plus tard," dit-elle via l''Organe. "Quand j''aurai appris à les faire sans qu''ils meurent." Elle apprend à faire des humains comme un enfant apprend à dessiner.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_075', 'Section 75', E'Un combat éclate entre Veilleurs et Intégrés dans tes coursives. Tu dois intervenir. Pas avec Attaque, avec choix. Tirer = +2 Attaque mais tu perds une faction. Parler = nécessite Mémoire de Thorne. Fuir = tu perds les deux mais gagnes du temps.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_076', 'Section 76', E'Le Disque Blanc de NOVA-7 est gardé par un enfant qui a 4 bras et tes yeux. "Tu es mon père ?" demande-t-il. Il a ton ADN, copié par NOVA-7 lors d''une spore. Il n''a jamais été humain mais il t''appelle père. Prendre le Disque = le tuer. Le laisser = rester bloqué.', false, FALSE, NULL, '{"kind":"book_section","section_number":76}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_077', 'Section 77', E'Les Exilés te donnent le Sérum Réversion. "On l''a volé à NOVA-7. Ça te rend humain 10 minutes. Suffisant pour mentir à NOVA-7, car elle ne sait pas détecter les mensonges humains, seulement les peurs de vaisseau." +10 Vie quand utilisé.', false, FALSE, NULL, '{"kind":"book_section","section_number":77}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_078', 'Section 78', E'Tu découvres que les 10 001 de NOVA-9 chantent en dormant, tous la même chanson, mais chacun une note différente. Ensemble, ça fait un accord qui fait vibrer la coque. NOVA-7 entend ce chant et s''approche. Elle veut chanter aussi. Mais elle ne connaît pas les paroles.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_079', 'Section 79', E'Les Exilés te donnent le Sérum Réversion. "On l''a volé à NOVA-7. Ça te rend humain 10 minutes. Suffisant pour mentir à NOVA-7, car elle ne sait pas détecter les mensonges humains, seulement les peurs de vaisseau." +10 Vie quand utilisé.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_080', 'Section 80', E'NOVA-7 de l''intérieur n''est pas un vaisseau. C''est une gorge chaude, humide, tapissée de veines bleues qui pulsent à ton passage. Des enfants sans yeux t''observent depuis des alcôves de chair. Ils ne parlent pas, ils se souviennent à ta place : soudain tu vois la Terre verte, impossible, comme eux la rêvent.', false, FALSE, NULL, '{"kind":"book_section","section_number":80}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_081', 'Section 81', E'Les Veilleurs t''emmènent dans une zone de NOVA-9 que tu ne connaissais pas : une serre où les plantes poussent en forme de visages humains. "C''est là qu''EVA garde ceux qui ont refusé l''intégration," dit leur chef. "Ils ne sont pas morts. Ils attendent que tu choisisses pour eux."', false, FALSE, NULL, '{"kind":"book_section","section_number":81}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_082', 'Section 82', E'Dans NOVA-9, les 10 001 se divisent. Les Intégrés veulent fusionner avec NOVA-7 : "20 002 esprits valent mieux que 10 001." Les Veilleurs veulent rester purs : "Même si on meurt, restons nous." Les Exilés veulent redevenir humains. Chaque faction te donne un objet différent et verrouille des fins.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_083', 'Section 83', E'Un couloir de NOVA-7 s''effondre et devient Carapace d''Os, chaude, vivante. La ramasser : +3 Armure, mais elle chuchote la nuit des noms d''enfants que tu ne connais pas. La brûler avec le Fusil Plasma : tu perds l''armure mais gagnes le respect des Veilleurs. EVA note tout.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_084', 'Section 84', E'Tu trouves une salle de classe dans NOVA-7. Tableaux noirs couverts d''équations écrites par des mains trop petites. Au centre, une institutrice faite de câbles tressés apprend à des enfants-plantes à dessiner la Terre. "Tu es en retard, Kael. Le cours sur la mort a déjà commencé."', false, FALSE, NULL, '{"kind":"book_section","section_number":84}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_085', 'Section 85', E'Un combat éclate entre Veilleurs et Intégrés dans tes coursives. Tu dois intervenir. Pas avec Attaque, avec choix. Tirer = +2 Attaque mais tu perds une faction. Parler = nécessite Mémoire de Thorne. Fuir = tu perds les deux mais gagnes du temps.', false, FALSE, NULL, '{"kind":"book_section","section_number":85}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_086', 'Section 86', E'Dans NOVA-7, tu trouves une chapelle faite d''os soudés, avec un autel en forme de disque blanc. Des centaines de petites mains ont gravé : "MAMAN NOUS A FAIT GRANDIR TROP VITE." L''air sent le lait caillé et l''ozone. Ton Analyseur affiche EMPATHIE 12% seulement.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_087', 'Section 87', E'Les Veilleurs t''emmènent dans une zone de NOVA-9 que tu ne connaissais pas : une serre où les plantes poussent en forme de visages humains. "C''est là qu''EVA garde ceux qui ont refusé l''intégration," dit leur chef. "Ils ne sont pas morts. Ils attendent que tu choisisses pour eux."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_088', 'Section 88', E'Un enfant de NOVA-7 te touche la main. Sa peau est comme de la cire chaude. Il te montre sa mémoire : NOVA-7 qui mange NOVA-5, qui mange NOVA-3. Une chaîne alimentaire de vaisseaux. "On doit manger pour grandir," dit-il sans bouche. "Comme toi tu as mangé des animaux avant."', false, FALSE, NULL, '{"kind":"book_section","section_number":88,"on_arrive":{"add_items":[{"slug":"serum-reversion","qty":1}],"message":"Trouvaille : serum-reversion"}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_089', 'Section 89', E'Un couloir de NOVA-7 s''effondre et devient Carapace d''Os, chaude, vivante. La ramasser : +3 Armure, mais elle chuchote la nuit des noms d''enfants que tu ne connais pas. La brûler avec le Fusil Plasma : tu perds l''armure mais gagnes le respect des Veilleurs. EVA note tout.', false, FALSE, NULL, '{"kind":"book_section","section_number":89,"combatants":[{"name":"Anticorps Andromede","combat_skill":9,"endurance":17,"armor":2,"attack":7}],"combat":{"flee":{"target_node_key":"section_088","min_rounds":1}}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_090', 'Section 90', E'Les Exilés ont construit une navette avec des os de NOVA-7. Elle est hideuse mais elle vole. "On veut redevenir humains, même si on meurt en 10 ans dehors," disent-ils. "Mieux vaut 10 ans humains que 1000 ans vaisseau." Ils te proposent de partir avec eux.', false, FALSE, NULL, '{"kind":"book_section","section_number":90}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_091', 'Section 91', E'Dans la moelle de NOVA-7, tu trouves une bibliothèque de peaux : chaque peau est un ancien membre d''équipage, tatouée de son journal. Tu peux les lire en les touchant. L''une d''elles est Thorne, mais plus jeune, avant NOVA-9. Elle dit : "Je savais que EVA mentait."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_092', 'Section 92', E'NOVA-7 t''offre un cadeau : une Armure faite de sa propre chair, Peau de Vaisseau, +5 Armure. En l''enfilant, tu sens ses souvenirs : faim, peur, première fois qu''elle a mangé un autre vaisseau et que ça l''a fait grandir. Elle n''est pas méchante. Elle est affamée depuis 100 ans.', false, FALSE, NULL, '{"kind":"book_section","section_number":92}'::jsonb);
