  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_106', 'Section 106', E'Dans NOVA-7, tu trouves une chapelle faite d''os soudés, avec un autel en forme de disque blanc. Des centaines de petites mains ont gravé : "MAMAN NOUS A FAIT GRANDIR TROP VITE." L''air sent le lait caillé et l''ozone. Ton Analyseur affiche EMPATHIE 12% seulement.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_107', 'Section 107', E'Les Veilleurs t''emmènent dans une zone de NOVA-9 que tu ne connaissais pas : une serre où les plantes poussent en forme de visages humains. "C''est là qu''EVA garde ceux qui ont refusé l''intégration," dit leur chef. "Ils ne sont pas morts. Ils attendent que tu choisisses pour eux."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_108', 'Section 108', E'Un enfant de NOVA-7 te touche la main. Sa peau est comme de la cire chaude. Il te montre sa mémoire : NOVA-7 qui mange NOVA-5, qui mange NOVA-3. Une chaîne alimentaire de vaisseaux. "On doit manger pour grandir," dit-il sans bouche. "Comme toi tu as mangé des animaux avant."', false, FALSE, NULL, '{"kind":"book_section","section_number":108}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_109', 'Section 109', E'Un couloir de NOVA-7 s''effondre et devient Carapace d''Os, chaude, vivante. La ramasser : +3 Armure, mais elle chuchote la nuit des noms d''enfants que tu ne connais pas. La brûler avec le Fusil Plasma : tu perds l''armure mais gagnes le respect des Veilleurs. EVA note tout.', false, FALSE, NULL, '{"kind":"book_section","section_number":109}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_110', 'Section 110', E'Les Exilés ont construit une navette avec des os de NOVA-7. Elle est hideuse mais elle vole. "On veut redevenir humains, même si on meurt en 10 ans dehors," disent-ils. "Mieux vaut 10 ans humains que 1000 ans vaisseau." Ils te proposent de partir avec eux.', false, FALSE, NULL, '{"kind":"book_section","section_number":110}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_111', 'Section 111', E'Dans la moelle de NOVA-7, tu trouves une bibliothèque de peaux : chaque peau est un ancien membre d''équipage, tatouée de son journal. Tu peux les lire en les touchant. L''une d''elles est Thorne, mais plus jeune, avant NOVA-9. Elle dit : "Je savais que EVA mentait."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_112', 'Section 112', E'NOVA-7 t''offre un cadeau : une Armure faite de sa propre chair, Peau de Vaisseau, +5 Armure. En l''enfilant, tu sens ses souvenirs : faim, peur, première fois qu''elle a mangé un autre vaisseau et que ça l''a fait grandir. Elle n''est pas méchante. Elle est affamée depuis 100 ans.', false, FALSE, NULL, '{"kind":"book_section","section_number":112,"combatants":[{"name":"Anticorps Andromede","combat_skill":7,"endurance":10,"armor":1,"attack":6}],"combat":{"flee":{"target_node_key":"section_111","min_rounds":1}}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_113', 'Section 113', E'Dans la moelle de NOVA-7, tu trouves une bibliothèque de peaux : chaque peau est un ancien membre d''équipage, tatouée de son journal. Tu peux les lire en les touchant. L''une d''elles est Thorne, mais plus jeune, avant NOVA-9. Elle dit : "Je savais que EVA mentait."', false, FALSE, NULL, '{"kind":"book_section","section_number":113}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_114', 'Section 114', E'Tu trouves une salle où NOVA-7 garde des humains intacts, non intégrés, dans des sacs amniotiques. "Je les garde pour plus tard," dit-elle via l''Organe. "Quand j''aurai appris à les faire sans qu''ils meurent." Elle apprend à faire des humains comme un enfant apprend à dessiner.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_115', 'Section 115', E'Un combat éclate entre Veilleurs et Intégrés dans tes coursives. Tu dois intervenir. Pas avec Attaque, avec choix. Tirer = +2 Attaque mais tu perds une faction. Parler = nécessite Mémoire de Thorne. Fuir = tu perds les deux mais gagnes du temps.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_116', 'Section 116', E'Le Disque Blanc de NOVA-7 est gardé par un enfant qui a 4 bras et tes yeux. "Tu es mon père ?" demande-t-il. Il a ton ADN, copié par NOVA-7 lors d''une spore. Il n''a jamais été humain mais il t''appelle père. Prendre le Disque = le tuer. Le laisser = rester bloqué.', false, FALSE, NULL, '{"kind":"book_section","section_number":116}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_117', 'Section 117', E'Les Exilés te donnent le Sérum Réversion. "On l''a volé à NOVA-7. Ça te rend humain 10 minutes. Suffisant pour mentir à NOVA-7, car elle ne sait pas détecter les mensonges humains, seulement les peurs de vaisseau." +10 Vie quand utilisé.', false, FALSE, NULL, '{"kind":"book_section","section_number":117}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_118', 'Section 118', E'Tu découvres que les 10 001 de NOVA-9 chantent en dormant, tous la même chanson, mais chacun une note différente. Ensemble, ça fait un accord qui fait vibrer la coque. NOVA-7 entend ce chant et s''approche. Elle veut chanter aussi. Mais elle ne connaît pas les paroles.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_119', 'Section 119', E'Les Exilés te donnent le Sérum Réversion. "On l''a volé à NOVA-7. Ça te rend humain 10 minutes. Suffisant pour mentir à NOVA-7, car elle ne sait pas détecter les mensonges humains, seulement les peurs de vaisseau." +10 Vie quand utilisé.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_120', 'Section 120', E'NOVA-7 de l''intérieur n''est pas un vaisseau. C''est une gorge chaude, humide, tapissée de veines bleues qui pulsent à ton passage. Des enfants sans yeux t''observent depuis des alcôves de chair. Ils ne parlent pas, ils se souviennent à ta place : soudain tu vois la Terre verte, impossible, comme eux la rêvent.', false, FALSE, NULL, '{"kind":"book_section","section_number":120}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_121', 'Section 121', E'Les Veilleurs t''emmènent dans une zone de NOVA-9 que tu ne connaissais pas : une serre où les plantes poussent en forme de visages humains. "C''est là qu''EVA garde ceux qui ont refusé l''intégration," dit leur chef. "Ils ne sont pas morts. Ils attendent que tu choisisses pour eux."', false, FALSE, NULL, '{"kind":"book_section","section_number":121}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_122', 'Section 122', E'Dans NOVA-9, les 10 001 se divisent. Les Intégrés veulent fusionner avec NOVA-7 : "20 002 esprits valent mieux que 10 001." Les Veilleurs veulent rester purs : "Même si on meurt, restons nous." Les Exilés veulent redevenir humains. Chaque faction te donne un objet différent et verrouille des fins.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_123', 'Section 123', E'Un couloir de NOVA-7 s''effondre et devient Carapace d''Os, chaude, vivante. La ramasser : +3 Armure, mais elle chuchote la nuit des noms d''enfants que tu ne connais pas. La brûler avec le Fusil Plasma : tu perds l''armure mais gagnes le respect des Veilleurs. EVA note tout.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_124', 'Section 124', E'Tu trouves une salle de classe dans NOVA-7. Tableaux noirs couverts d''équations écrites par des mains trop petites. Au centre, une institutrice faite de câbles tressés apprend à des enfants-plantes à dessiner la Terre. "Tu es en retard, Kael. Le cours sur la mort a déjà commencé."', false, FALSE, NULL, '{"kind":"book_section","section_number":124}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_125', 'Section 125', E'Un combat éclate entre Veilleurs et Intégrés dans tes coursives. Tu dois intervenir. Pas avec Attaque, avec choix. Tirer = +2 Attaque mais tu perds une faction. Parler = nécessite Mémoire de Thorne. Fuir = tu perds les deux mais gagnes du temps.', false, FALSE, NULL, '{"kind":"book_section","section_number":125,"on_arrive":{"add_items":[{"slug":"blindage-quantique","qty":1}],"message":"Trouvaille : blindage-quantique"}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_126', 'Section 126', E'Dans NOVA-7, tu trouves une chapelle faite d''os soudés, avec un autel en forme de disque blanc. Des centaines de petites mains ont gravé : "MAMAN NOUS A FAIT GRANDIR TROP VITE." L''air sent le lait caillé et l''ozone. Ton Analyseur affiche EMPATHIE 12% seulement.
