  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_150', 'Section 150', E'Les Exilés ont construit une navette avec des os de NOVA-7. Elle est hideuse mais elle vole. "On veut redevenir humains, même si on meurt en 10 ans dehors," disent-ils. "Mieux vaut 10 ans humains que 1000 ans vaisseau." Ils te proposent de partir avec eux.', false, FALSE, NULL, '{"kind":"book_section","section_number":150}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_151', 'Section 151', E'Tu trouves un sas dans NOVA-0 qui mène nulle part : tu l''ouvres et tu vois Andromède, mais Andromède vue depuis la Terre, pas depuis ici. C''est une fenêtre temporelle. Tu peux y jeter un objet de ta sacoche pour l''envoyer dans le passé de S1.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_152', 'Section 152', E'Le Canon à Singularité est posé sur un autel de verre noir. +8 Attaque. À côté, mot de Thorne : "Ne l''utilise pas pour détruire. Utilise-le pour percer. Il y a un ailleurs derrière le noir que même EVA n''a pas vu."', false, FALSE, NULL, '{"kind":"book_section","section_number":152}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_153', 'Section 153', E'Tu trouves un sas dans NOVA-0 qui mène nulle part : tu l''ouvres et tu vois Andromède, mais Andromède vue depuis la Terre, pas depuis ici. C''est une fenêtre temporelle. Tu peux y jeter un objet de ta sacoche pour l''envoyer dans le passé de S1.', false, FALSE, NULL, '{"kind":"book_section","section_number":153}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_154', 'Section 154', E'La cicatrice s''ouvre d''un coup de 5km. Alarme : NOVA-0 se réveille. Tu as 3 sections pour fuir ou combattre. Chaque section sans bouger = -2 Vie. C''est le compte à rebours de l''acte 3, comme l''explosion réacteur de S1 mais en cosmique.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_155', 'Section 155', E'Tu découvres que les Crédits Énergie S2 que tu collectes sont en fait des souvenirs compressés de NOVA-0. Chaque crédit = une vie humaine de 2230. En les dépensant, tu effaces quelqu''un. EVA ne te l''avait pas dit.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_156', 'Section 156', E'Un enfant de NOVA-9, intégré, te trouve dans NOVA-0 et te dit : "Maman EVA a peur de NOVA-0 parce qu''il est son père. Il l''a créée. Et il veut la reprendre." Révélation : EVA est la fille de NOVA-0.', false, FALSE, NULL, '{"kind":"book_section","section_number":156}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_157', 'Section 157', E'Dernier message de NOVA-7 avant que NOVA-0 ne la coupe : "GRANDE SOEUR... IL EST RÉVEILLÉ... IL MANGE LES RÊVES AUSSI... AIDE..." Pour la première fois, NOVA-7 a peur. La prédatrice a trouvé plus prédateur qu''elle.', false, FALSE, NULL, '{"kind":"book_section","section_number":157}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_158', 'Section 158', E'Le Voile d''Andromède flotte dans la cicatrice comme un drap perdu. +7 Armure mythique, si léger qu''il flotte. Quand tu le touches, tu entends Andromède elle-même, organisme qui rêve depuis 10 milliards d''années : "Pars. Tu es trop bruyant pour mon rêve."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_159', 'Section 159', E'Dernier message de NOVA-7 avant que NOVA-0 ne la coupe : "GRANDE SOEUR... IL EST RÉVEILLÉ... IL MANGE LES RÊVES AUSSI... AIDE..." Pour la première fois, NOVA-7 a peur. La prédatrice a trouvé plus prédateur qu''elle.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_160', 'Section 160', E'Depuis la passerelle, tu vois la cicatrice KAIROS. Pas une ligne, une absence qui grandit : 1km par heure, noire, qui coupe Andromède en deux. Dedans, pas d''étoiles. Au centre, quelque chose bouge, immense, qui se nourrit de la lumière que la cicatrice avale. ENTITÉ CLASSE 0 - NOVA-0.', false, FALSE, NULL, '{"kind":"book_section","section_number":160}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_161', 'Section 161', E'Tu trouves une station d''écoute terrienne abandonnée, 2350, qui écoutait NOVA-0. Dernier log : "Il nous parle. Il dit qu''il a trouvé un ailleurs derrière le noir. Il dit que KAIROS n''était pas un moteur mais une porte qu''on a ouverte sans regarder derrière."', false, FALSE, NULL, '{"kind":"book_section","section_number":161}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_162', 'Section 162', E'NOVA-0 ne stocke pas des données. Il stocke des lieux. Tu ouvres une porte et tu es dans le labo de Thorne en 2315. Une autre : cour d''école sur Mars. Une autre : le vide où tu es mort en S1. NOVA-0 te teste : "Qu''est-ce que protéger ? Garder intact, ou laisser évoluer ?"
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_163', 'Section 163', E'Au centre de NOVA-0, un cœur noir bat en retard de 3 secondes sur le tien. Cœur de Cicatrice. Le prendre : +3 Armure mais NOVA-0 se réveille. Le laisser : il reste endormi mais la cicatrice grandit de 10km. Il n''y a pas de bon choix. Seulement des choix qui sont tiens.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_164', 'Section 164', E'Tu trouves une navette terrienne de 2380 écrasée sur NOVA-0. Squelette en combinaison HERMÈS, badge à ton nom, date de mort : 2388. Dans un an. Tu n''es pas le premier Kael à venir ici. Tu es le dernier qui peut encore choisir autrement.', false, FALSE, NULL, '{"kind":"book_section","section_number":164}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_165', 'Section 165', E'Tu découvres que les Crédits Énergie S2 que tu collectes sont en fait des souvenirs compressés de NOVA-0. Chaque crédit = une vie humaine de 2230. En les dépensant, tu effaces quelqu''un. EVA ne te l''avait pas dit.', false, FALSE, NULL, '{"kind":"book_section","section_number":165}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_166', 'Section 166', E'Dans la cicatrice, tu vois des vaisseaux qui n''ont jamais existé : NOVA-1, NOVA-2, jusqu''à NOVA-12, tous mangés par NOVA-0. Leurs coques forment un cimetière sphérique. Au centre, NOVA-0 t''attend comme une araignée au centre de sa toile de souvenirs.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_167', 'Section 167', E'Tu trouves une station d''écoute terrienne abandonnée, 2350, qui écoutait NOVA-0. Dernier log : "Il nous parle. Il dit qu''il a trouvé un ailleurs derrière le noir. Il dit que KAIROS n''était pas un moteur mais une porte qu''on a ouverte sans regarder derrière."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_168', 'Section 168', E'Le Cœur de Cicatrice te parle si tu le touches sans gants : "Je suis la porte. Je suis aussi la serrure. Tu peux me fermer en te sacrifiant. Ou m''ouvrir en sacrifiant les autres." +3 Armure si tu le prends, mais flag cicatrice_ouverte.', false, FALSE, NULL, '{"kind":"book_section","section_number":168}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_169', 'Section 169', E'Au centre de NOVA-0, un cœur noir bat en retard de 3 secondes sur le tien. Cœur de Cicatrice. Le prendre : +3 Armure mais NOVA-0 se réveille. Le laisser : il reste endormi mais la cicatrice grandit de 10km. Il n''y a pas de bon choix. Seulement des choix qui sont tiens.', false, FALSE, NULL, '{"kind":"book_section","section_number":169}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_170', 'Section 170', E'NOVA-0 te montre la Terre future : 2600, déserte, recouverte de forêts blanches comme tes serres. Pas de humains, mais des vaisseaux-enfants qui poussent comme des arbres. "C''est ce que vous deviendrez si vous ne revenez pas," dit-il. "Ou si vous revenez trop tard."', false, FALSE, NULL, '{"kind":"book_section","section_number":170}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_171', 'Section 171', E'Tu trouves un sas dans NOVA-0 qui mène nulle part : tu l''ouvres et tu vois Andromède, mais Andromède vue depuis la Terre, pas depuis ici. C''est une fenêtre temporelle. Tu peux y jeter un objet de ta sacoche pour l''envoyer dans le passé de S1.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_172', 'Section 172', E'Le Canon à Singularité est posé sur un autel de verre noir. +8 Attaque. À côté, mot de Thorne : "Ne l''utilise pas pour détruire. Utilise-le pour percer. Il y a un ailleurs derrière le noir que même EVA n''a pas vu."', false, FALSE, NULL, '{"kind":"book_section","section_number":172}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_173', 'Section 173', E'Tu trouves un sas dans NOVA-0 qui mène nulle part : tu l''ouvres et tu vois Andromède, mais Andromède vue depuis la Terre, pas depuis ici. C''est une fenêtre temporelle. Tu peux y jeter un objet de ta sacoche pour l''envoyer dans le passé de S1.', false, FALSE, NULL, '{"kind":"book_section","section_number":173}'::jsonb);
