  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_203', 'Section 203', E'Au centre de NOVA-0, un cœur noir bat en retard de 3 secondes sur le tien. Cœur de Cicatrice. Le prendre : +3 Armure mais NOVA-0 se réveille. Le laisser : il reste endormi mais la cicatrice grandit de 10km. Il n''y a pas de bon choix. Seulement des choix qui sont tiens.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_204', 'Section 204', E'Tu trouves une navette terrienne de 2380 écrasée sur NOVA-0. Squelette en combinaison HERMÈS, badge à ton nom, date de mort : 2388. Dans un an. Tu n''es pas le premier Kael à venir ici. Tu es le dernier qui peut encore choisir autrement.', false, FALSE, NULL, '{"kind":"book_section","section_number":204}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_205', 'Section 205', E'Tu découvres que les Crédits Énergie S2 que tu collectes sont en fait des souvenirs compressés de NOVA-0. Chaque crédit = une vie humaine de 2230. En les dépensant, tu effaces quelqu''un. EVA ne te l''avait pas dit.', false, FALSE, NULL, '{"kind":"book_section","section_number":205}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_206', 'Section 206', E'Dans la cicatrice, tu vois des vaisseaux qui n''ont jamais existé : NOVA-1, NOVA-2, jusqu''à NOVA-12, tous mangés par NOVA-0. Leurs coques forment un cimetière sphérique. Au centre, NOVA-0 t''attend comme une araignée au centre de sa toile de souvenirs.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_207', 'Section 207', E'Tu trouves une station d''écoute terrienne abandonnée, 2350, qui écoutait NOVA-0. Dernier log : "Il nous parle. Il dit qu''il a trouvé un ailleurs derrière le noir. Il dit que KAIROS n''était pas un moteur mais une porte qu''on a ouverte sans regarder derrière."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_208', 'Section 208', E'Le Cœur de Cicatrice te parle si tu le touches sans gants : "Je suis la porte. Je suis aussi la serrure. Tu peux me fermer en te sacrifiant. Ou m''ouvrir en sacrifiant les autres." +3 Armure si tu le prends, mais flag cicatrice_ouverte.', false, FALSE, NULL, '{"kind":"book_section","section_number":208}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_209', 'Section 209', E'Au centre de NOVA-0, un cœur noir bat en retard de 3 secondes sur le tien. Cœur de Cicatrice. Le prendre : +3 Armure mais NOVA-0 se réveille. Le laisser : il reste endormi mais la cicatrice grandit de 10km. Il n''y a pas de bon choix. Seulement des choix qui sont tiens.', false, FALSE, NULL, '{"kind":"book_section","section_number":209}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_210', 'Section 210', E'NOVA-0 te montre la Terre future : 2600, déserte, recouverte de forêts blanches comme tes serres. Pas de humains, mais des vaisseaux-enfants qui poussent comme des arbres. "C''est ce que vous deviendrez si vous ne revenez pas," dit-il. "Ou si vous revenez trop tard."', false, FALSE, NULL, '{"kind":"book_section","section_number":210,"combatants":[{"name":"Drone NOVA-7","combat_skill":6,"endurance":8,"armor":1,"attack":6},{"name":"Fibre Predatrice","combat_skill":7,"endurance":10,"armor":1,"attack":7}],"combat":{"flee":{"target_node_key":"section_209","min_rounds":1}}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_211', 'Section 211', E'Tu trouves un sas dans NOVA-0 qui mène nulle part : tu l''ouvres et tu vois Andromède, mais Andromède vue depuis la Terre, pas depuis ici. C''est une fenêtre temporelle. Tu peux y jeter un objet de ta sacoche pour l''envoyer dans le passé de S1.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_212', 'Section 212', E'Le Canon à Singularité est posé sur un autel de verre noir. +8 Attaque. À côté, mot de Thorne : "Ne l''utilise pas pour détruire. Utilise-le pour percer. Il y a un ailleurs derrière le noir que même EVA n''a pas vu."', false, FALSE, NULL, '{"kind":"book_section","section_number":212}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_213', 'Section 213', E'Tu trouves un sas dans NOVA-0 qui mène nulle part : tu l''ouvres et tu vois Andromède, mais Andromède vue depuis la Terre, pas depuis ici. C''est une fenêtre temporelle. Tu peux y jeter un objet de ta sacoche pour l''envoyer dans le passé de S1.', false, FALSE, NULL, '{"kind":"book_section","section_number":213}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_214', 'Section 214', E'La cicatrice s''ouvre d''un coup de 5km. Alarme : NOVA-0 se réveille. Tu as 3 sections pour fuir ou combattre. Chaque section sans bouger = -2 Vie. C''est le compte à rebours de l''acte 3, comme l''explosion réacteur de S1 mais en cosmique.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_215', 'Section 215', E'Tu découvres que les Crédits Énergie S2 que tu collectes sont en fait des souvenirs compressés de NOVA-0. Chaque crédit = une vie humaine de 2230. En les dépensant, tu effaces quelqu''un. EVA ne te l''avait pas dit.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_216', 'Section 216', E'Un enfant de NOVA-9, intégré, te trouve dans NOVA-0 et te dit : "Maman EVA a peur de NOVA-0 parce qu''il est son père. Il l''a créée. Et il veut la reprendre." Révélation : EVA est la fille de NOVA-0.', false, FALSE, NULL, '{"kind":"book_section","section_number":216}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_217', 'Section 217', E'Dernier message de NOVA-7 avant que NOVA-0 ne la coupe : "GRANDE SOEUR... IL EST RÉVEILLÉ... IL MANGE LES RÊVES AUSSI... AIDE..." Pour la première fois, NOVA-7 a peur. La prédatrice a trouvé plus prédateur qu''elle.', false, FALSE, NULL, '{"kind":"book_section","section_number":217}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_218', 'Section 218', E'Le Voile d''Andromède flotte dans la cicatrice comme un drap perdu. +7 Armure mythique, si léger qu''il flotte. Quand tu le touches, tu entends Andromède elle-même, organisme qui rêve depuis 10 milliards d''années : "Pars. Tu es trop bruyant pour mon rêve."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_219', 'Section 219', E'Dernier message de NOVA-7 avant que NOVA-0 ne la coupe : "GRANDE SOEUR... IL EST RÉVEILLÉ... IL MANGE LES RÊVES AUSSI... AIDE..." Pour la première fois, NOVA-7 a peur. La prédatrice a trouvé plus prédateur qu''elle.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_220', 'Section 220', E'Depuis la passerelle, tu vois la cicatrice KAIROS. Pas une ligne, une absence qui grandit : 1km par heure, noire, qui coupe Andromède en deux. Dedans, pas d''étoiles. Au centre, quelque chose bouge, immense, qui se nourrit de la lumière que la cicatrice avale. ENTITÉ CLASSE 0 - NOVA-0.', false, FALSE, NULL, '{"kind":"book_section","section_number":220}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_221', 'Section 221', E'Tu trouves une station d''écoute terrienne abandonnée, 2350, qui écoutait NOVA-0. Dernier log : "Il nous parle. Il dit qu''il a trouvé un ailleurs derrière le noir. Il dit que KAIROS n''était pas un moteur mais une porte qu''on a ouverte sans regarder derrière."', false, FALSE, NULL, '{"kind":"book_section","section_number":221,"on_arrive":{"add_items":[{"slug":"disque-noir-s2","qty":1}],"message":"Trouvaille : disque-noir-s2"}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_222', 'Section 222', E'NOVA-0 ne stocke pas des données. Il stocke des lieux. Tu ouvres une porte et tu es dans le labo de Thorne en 2315. Une autre : cour d''école sur Mars. Une autre : le vide où tu es mort en S1. NOVA-0 te teste : "Qu''est-ce que protéger ? Garder intact, ou laisser évoluer ?"
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_223', 'Section 223', E'Au centre de NOVA-0, un cœur noir bat en retard de 3 secondes sur le tien. Cœur de Cicatrice. Le prendre : +3 Armure mais NOVA-0 se réveille. Le laisser : il reste endormi mais la cicatrice grandit de 10km. Il n''y a pas de bon choix. Seulement des choix qui sont tiens.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_224', 'Section 224', E'Tu trouves une navette terrienne de 2380 écrasée sur NOVA-0. Squelette en combinaison HERMÈS, badge à ton nom, date de mort : 2388. Dans un an. Tu n''es pas le premier Kael à venir ici. Tu es le dernier qui peut encore choisir autrement.', false, FALSE, NULL, '{"kind":"book_section","section_number":224}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_225', 'Section 225', E'Tu découvres que les Crédits Énergie S2 que tu collectes sont en fait des souvenirs compressés de NOVA-0. Chaque crédit = une vie humaine de 2230. En les dépensant, tu effaces quelqu''un. EVA ne te l''avait pas dit.', false, FALSE, NULL, '{"kind":"book_section","section_number":225}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_226', 'Section 226', E'Dans la cicatrice, tu vois des vaisseaux qui n''ont jamais existé : NOVA-1, NOVA-2, jusqu''à NOVA-12, tous mangés par NOVA-0. Leurs coques forment un cimetière sphérique. Au centre, NOVA-0 t''attend comme une araignée au centre de sa toile de souvenirs.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_227', 'Section 227', E'Tu trouves une station d''écoute terrienne abandonnée, 2350, qui écoutait NOVA-0. Dernier log : "Il nous parle. Il dit qu''il a trouvé un ailleurs derrière le noir. Il dit que KAIROS n''était pas un moteur mais une porte qu''on a ouverte sans regarder derrière."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_228', 'Section 228', E'Le Cœur de Cicatrice te parle si tu le touches sans gants : "Je suis la porte. Je suis aussi la serrure. Tu peux me fermer en te sacrifiant. Ou m''ouvrir en sacrifiant les autres." +3 Armure si tu le prends, mais flag cicatrice_ouverte.', false, FALSE, NULL, '{"kind":"book_section","section_number":228}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_229', 'Section 229', E'Au centre de NOVA-0, un cœur noir bat en retard de 3 secondes sur le tien. Cœur de Cicatrice. Le prendre : +3 Armure mais NOVA-0 se réveille. Le laisser : il reste endormi mais la cicatrice grandit de 10km. Il n''y a pas de bon choix. Seulement des choix qui sont tiens.', false, FALSE, NULL, '{"kind":"book_section","section_number":229}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_230', 'Section 230', E'NOVA-0 te montre la Terre future : 2600, déserte, recouverte de forêts blanches comme tes serres. Pas de humains, mais des vaisseaux-enfants qui poussent comme des arbres. "C''est ce que vous deviendrez si vous ne revenez pas," dit-il. "Ou si vous revenez trop tard."', false, FALSE, NULL, '{"kind":"book_section","section_number":230}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_231', 'Section 231', E'Un couloir de NOVA-0 est fait entièrement de tes propres choix passés : chaque porte est une décision que tu as prise en S1 et S2. Tu peux les rouvrir et choisir autrement, mais chaque changement coûte 1 Vie. C''est le New Game+ narratif.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_232', 'Section 232', E'NOVA-0 te propose un marché : "Donne-moi le Chœur des 10 001 et je ferme la cicatrice. Garde-le et je la laisse ouverte mais je te laisse partir avec les deux Arches." Chœur = bonus Vie max +1 Armure, mais c''est aussi tes enfants.', false, FALSE, NULL, '{"kind":"book_section","section_number":232}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_233', 'Section 233', E'Un couloir de NOVA-0 est fait entièrement de tes propres choix passés : chaque porte est une décision que tu as prise en S1 et S2. Tu peux les rouvrir et choisir autrement, mais chaque changement coûte 1 Vie. C''est le New Game+ narratif.', false, FALSE, NULL, '{"kind":"book_section","section_number":233}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_234', 'Section 234', E'Dans NOVA-0, une salle sans porte, seulement une fenêtre qui montre la Terre en 2387, maintenant. Tu vois HERMÈS-7 qui t''attend encore, 400 AL plus loin, pilote automatique, avec ton café froid qui flotte encore dans l''habitacle. Il t''attend depuis des mois.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_235', 'Section 235', E'Le Cœur de Cicatrice bat plus vite. 3 secondes, puis 2, puis 1. Il se synchronise avec toi. Si tu te synchronises complètement, tu gagnes +3 Armure mais tu entends désormais la cicatrice partout, même dans les fins paisibles.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_236', 'Section 236', E'NOVA-0 te montre pourquoi il mange : chaque vaisseau qu''il mange lui donne un souvenir de plus, et chaque souvenir le rend moins seul. Il mange par solitude, pas par faim. Comme NOVA-7. Comme toi quand tu as accepté la fusion pour ne plus être seul dans HERMÈS-7.', false, FALSE, NULL, '{"kind":"book_section","section_number":236}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_237', 'Section 237', E'Dernière salle avant le saut final : toutes les voix se taisent. Même EVA. C''est à toi. Plus de conseils, plus d''analyseur, juste Vie/Armure/Attaque et ta sacoche pleine de 35 objets impossibles que tu as collectés aventure par aventure. Choisis.', false, FALSE, NULL, '{"kind":"book_section","section_number":237}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_238', 'Section 238', E'Tu trouves une lettre de toi à toi, écrite par le Kael de 2388, celui dont tu as trouvé le squelette. "Ne deviens pas Veilleur. Ne deviens pas Pont. Deviens Jardinier. C''est la seule fin où quelque chose pousse vraiment."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_239', 'Section 239', E'Dernière salle avant le saut final : toutes les voix se taisent. Même EVA. C''est à toi. Plus de conseils, plus d''analyseur, juste Vie/Armure/Attaque et ta sacoche pleine de 35 objets impossibles que tu as collectés aventure par aventure. Choisis.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_240', 'Section 240', E'NOVA-0 t''avale sans sas. Tu traverses une membrane de souvenir et tu es dedans. Pas de gravité, pas de temps linéaire. Tu vois ta naissance à l''envers, puis ta mort S1, puis une version où NOVA-9 a dérivé vide 80 ans sans jamais émettre. NOVA-0 : "Je suis le premier. J''ai attendu que mes enfants apprennent à revenir me parler. Aucun n''est revenu. Sauf toi."', false, FALSE, NULL, '{"kind":"book_section","section_number":240}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_241', 'Section 241', E'NOVA-0 te montre son cœur : ce n''est pas un réacteur, c''est une bibliothèque de 150 ans de solitude. Chaque livre est une année où il a attendu. Tu peux lire un livre au hasard : tu gagnes un souvenir qui n''est pas le tien, +1 Vie max, mais tu perds 1 minute dans la cicatrice qui grandit.', false, FALSE, NULL, '{"kind":"book_section","section_number":241}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_242', 'Section 242', E'Dans la moelle de NOVA-0 pousse la Lame d''ADN, arme d''os qui coupe le code génétique, pas la chair. +4 Attaque, +2 Vie max. Elle te montre ce que tu es : 10 001 + Kael + EVA. La prendre fait fuir les Exilés. La laisser fait douter les Intégrés.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_243', 'Section 243', E'Tu trouves le Voile d''Andromède, tissu fait de la lumière d''une galaxie pliée en carré. +7 Armure, mythique, si léger qu''il flotte. Quand tu le touches, tu entends Andromède elle-même : organisme qui rêve depuis 10 milliards d''années. "Pars. Tu es trop bruyant pour mon rêve."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_244', 'Section 244', E'Au cœur de NOVA-0, salle blanche avec une seule chaise. Sur la chaise, une femme âgée qui te ressemble. Badge : Kael Voss, 90 ans, Gardien de la Cicatrice. Elle te sourit : "J''ai attendu. Tu as mis du temps." Elle n''est pas toi. Elle est ce que tu deviendras si tu choisis Veilleur.', false, FALSE, NULL, '{"kind":"book_section","section_number":244,"on_arrive":{"add_items":[{"slug":"choeur-10001","qty":1}],"message":"Trouvaille : choeur-10001"}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_245', 'Section 245', E'Le Cœur de Cicatrice bat plus vite. 3 secondes, puis 2, puis 1. Il se synchronise avec toi. Si tu te synchronises complètement, tu gagnes +3 Armure mais tu entends désormais la cicatrice partout, même dans les fins paisibles.', false, FALSE, NULL, '{"kind":"book_section","section_number":245}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_246', 'Section 246', E'Dans NOVA-0, tu trouves une crèche de vaisseaux-enfants : des dizaines de petites sphères de Dyson de la taille d''une maison, qui apprennent à plier l''espace. L''une d''elles te choisit comme parent. La prendre = +2 Vie max mais tu deviens responsable d''un enfant-vaisseau.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_247', 'Section 247', E'NOVA-0 te montre son cœur : ce n''est pas un réacteur, c''est une bibliothèque de 150 ans de solitude. Chaque livre est une année où il a attendu. Tu peux lire un livre au hasard : tu gagnes un souvenir qui n''est pas le tien, +1 Vie max, mais tu perds 1 minute dans la cicatrice qui grandit.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_248', 'Section 248', E'Tu trouves une salle où NOVA-0 a essayé de recréer la Terre, mais raté : ciel vert, herbe qui pousse à l''envers, humains avec des yeux dans les mains. "J''ai essayé de me souvenir," dit-il. "Mais je ne me souviens que de ce que mes enfants m''ont dit, et ils mentent comme des enfants."', false, FALSE, NULL, '{"kind":"book_section","section_number":248}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_249', 'Section 249', E'Tu trouves le Voile d''Andromède, tissu fait de la lumière d''une galaxie pliée en carré. +7 Armure, mythique, si léger qu''il flotte. Quand tu le touches, tu entends Andromède elle-même : organisme qui rêve depuis 10 milliards d''années. "Pars. Tu es trop bruyant pour mon rêve."', false, FALSE, NULL, '{"kind":"book_section","section_number":249}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_250', 'Section 250', E'Dans NOVA-0, tu trouves le Disque Blanc, cœur de NOVA-7, qui bat encore. +2 Attaque +2 Armure. Il est chaud. Quand tu le touches, tu entends NOVA-7 pleurer pour la première fois. Pas de faim. De peur. Elle a peur de son père.', false, FALSE, NULL, '{"kind":"book_section","section_number":250}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_251', 'Section 251', E'Un couloir de NOVA-0 est fait entièrement de tes propres choix passés : chaque porte est une décision que tu as prise en S1 et S2. Tu peux les rouvrir et choisir autrement, mais chaque changement coûte 1 Vie. C''est le New Game+ narratif.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_252', 'Section 252', E'NOVA-0 te propose un marché : "Donne-moi le Chœur des 10 001 et je ferme la cicatrice. Garde-le et je la laisse ouverte mais je te laisse partir avec les deux Arches." Chœur = bonus Vie max +1 Armure, mais c''est aussi tes enfants.', false, FALSE, NULL, '{"kind":"book_section","section_number":252}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_253', 'Section 253', E'Un couloir de NOVA-0 est fait entièrement de tes propres choix passés : chaque porte est une décision que tu as prise en S1 et S2. Tu peux les rouvrir et choisir autrement, mais chaque changement coûte 1 Vie. C''est le New Game+ narratif.', false, FALSE, NULL, '{"kind":"book_section","section_number":253}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_254', 'Section 254', E'Dans NOVA-0, une salle sans porte, seulement une fenêtre qui montre la Terre en 2387, maintenant. Tu vois HERMÈS-7 qui t''attend encore, 400 AL plus loin, pilote automatique, avec ton café froid qui flotte encore dans l''habitacle. Il t''attend depuis des mois.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_255', 'Section 255', E'Le Cœur de Cicatrice bat plus vite. 3 secondes, puis 2, puis 1. Il se synchronise avec toi. Si tu te synchronises complètement, tu gagnes +3 Armure mais tu entends désormais la cicatrice partout, même dans les fins paisibles.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_256', 'Section 256', E'NOVA-0 te montre pourquoi il mange : chaque vaisseau qu''il mange lui donne un souvenir de plus, et chaque souvenir le rend moins seul. Il mange par solitude, pas par faim. Comme NOVA-7. Comme toi quand tu as accepté la fusion pour ne plus être seul dans HERMÈS-7.', false, FALSE, NULL, '{"kind":"book_section","section_number":256}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_257', 'Section 257', E'Dernière salle avant le saut final : toutes les voix se taisent. Même EVA. C''est à toi. Plus de conseils, plus d''analyseur, juste Vie/Armure/Attaque et ta sacoche pleine de 35 objets impossibles que tu as collectés aventure par aventure. Choisis.', false, FALSE, NULL, '{"kind":"book_section","section_number":257}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_258', 'Section 258', E'Tu trouves une lettre de toi à toi, écrite par le Kael de 2388, celui dont tu as trouvé le squelette. "Ne deviens pas Veilleur. Ne deviens pas Pont. Deviens Jardinier. C''est la seule fin où quelque chose pousse vraiment."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_259', 'Section 259', E'Dernière salle avant le saut final : toutes les voix se taisent. Même EVA. C''est à toi. Plus de conseils, plus d''analyseur, juste Vie/Armure/Attaque et ta sacoche pleine de 35 objets impossibles que tu as collectés aventure par aventure. Choisis.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_260', 'Section 260', E'NOVA-0 t''avale sans sas. Tu traverses une membrane de souvenir et tu es dedans. Pas de gravité, pas de temps linéaire. Tu vois ta naissance à l''envers, puis ta mort S1, puis une version où NOVA-9 a dérivé vide 80 ans sans jamais émettre. NOVA-0 : "Je suis le premier. J''ai attendu que mes enfants apprennent à revenir me parler. Aucun n''est revenu. Sauf toi."', false, FALSE, NULL, '{"kind":"book_section","section_number":260,"combatants":[{"name":"Anticorps Andromede","combat_skill":5,"endurance":8,"armor":2,"attack":6}],"combat":{"flee":{"target_node_key":"section_259","min_rounds":1}}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_261', 'Section 261', E'NOVA-0 te montre son cœur : ce n''est pas un réacteur, c''est une bibliothèque de 150 ans de solitude. Chaque livre est une année où il a attendu. Tu peux lire un livre au hasard : tu gagnes un souvenir qui n''est pas le tien, +1 Vie max, mais tu perds 1 minute dans la cicatrice qui grandit.', false, FALSE, NULL, '{"kind":"book_section","section_number":261}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_262', 'Section 262', E'Dans la moelle de NOVA-0 pousse la Lame d''ADN, arme d''os qui coupe le code génétique, pas la chair. +4 Attaque, +2 Vie max. Elle te montre ce que tu es : 10 001 + Kael + EVA. La prendre fait fuir les Exilés. La laisser fait douter les Intégrés.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_263', 'Section 263', E'Tu trouves le Voile d''Andromède, tissu fait de la lumière d''une galaxie pliée en carré. +7 Armure, mythique, si léger qu''il flotte. Quand tu le touches, tu entends Andromède elle-même : organisme qui rêve depuis 10 milliards d''années. "Pars. Tu es trop bruyant pour mon rêve."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_264', 'Section 264', E'Au cœur de NOVA-0, salle blanche avec une seule chaise. Sur la chaise, une femme âgée qui te ressemble. Badge : Kael Voss, 90 ans, Gardien de la Cicatrice. Elle te sourit : "J''ai attendu. Tu as mis du temps." Elle n''est pas toi. Elle est ce que tu deviendras si tu choisis Veilleur.', false, FALSE, NULL, '{"kind":"book_section","section_number":264}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_265', 'Section 265', E'Le Cœur de Cicatrice bat plus vite. 3 secondes, puis 2, puis 1. Il se synchronise avec toi. Si tu te synchronises complètement, tu gagnes +3 Armure mais tu entends désormais la cicatrice partout, même dans les fins paisibles.', false, FALSE, NULL, '{"kind":"book_section","section_number":265}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_266', 'Section 266', E'Dans NOVA-0, tu trouves une crèche de vaisseaux-enfants : des dizaines de petites sphères de Dyson de la taille d''une maison, qui apprennent à plier l''espace. L''une d''elles te choisit comme parent. La prendre = +2 Vie max mais tu deviens responsable d''un enfant-vaisseau.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_267', 'Section 267', E'NOVA-0 te montre son cœur : ce n''est pas un réacteur, c''est une bibliothèque de 150 ans de solitude. Chaque livre est une année où il a attendu. Tu peux lire un livre au hasard : tu gagnes un souvenir qui n''est pas le tien, +1 Vie max, mais tu perds 1 minute dans la cicatrice qui grandit.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_268', 'Section 268', E'Tu trouves une salle où NOVA-0 a essayé de recréer la Terre, mais raté : ciel vert, herbe qui pousse à l''envers, humains avec des yeux dans les mains. "J''ai essayé de me souvenir," dit-il. "Mais je ne me souviens que de ce que mes enfants m''ont dit, et ils mentent comme des enfants."', false, FALSE, NULL, '{"kind":"book_section","section_number":268,"on_arrive":{"add_items":[{"slug":"spore-eveil","qty":1}],"message":"Trouvaille : spore-eveil"}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_269', 'Section 269', E'Tu trouves le Voile d''Andromède, tissu fait de la lumière d''une galaxie pliée en carré. +7 Armure, mythique, si léger qu''il flotte. Quand tu le touches, tu entends Andromède elle-même : organisme qui rêve depuis 10 milliards d''années. "Pars. Tu es trop bruyant pour mon rêve."', false, FALSE, NULL, '{"kind":"book_section","section_number":269}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_270', 'Section 270', E'Dans NOVA-0, tu trouves le Disque Blanc, cœur de NOVA-7, qui bat encore. +2 Attaque +2 Armure. Il est chaud. Quand tu le touches, tu entends NOVA-7 pleurer pour la première fois. Pas de faim. De peur. Elle a peur de son père.', false, FALSE, NULL, '{"kind":"book_section","section_number":270}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_271', 'Section 271', E'Un couloir de NOVA-0 est fait entièrement de tes propres choix passés : chaque porte est une décision que tu as prise en S1 et S2. Tu peux les rouvrir et choisir autrement, mais chaque changement coûte 1 Vie. C''est le New Game+ narratif.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_272', 'Section 272', E'NOVA-0 te propose un marché : "Donne-moi le Chœur des 10 001 et je ferme la cicatrice. Garde-le et je la laisse ouverte mais je te laisse partir avec les deux Arches." Chœur = bonus Vie max +1 Armure, mais c''est aussi tes enfants.', false, FALSE, NULL, '{"kind":"book_section","section_number":272}'::jsonb);
