  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_300', 'Section 300', E'NOVA-0 t''avale sans sas. Tu traverses une membrane de souvenir et tu es dedans. Pas de gravité, pas de temps linéaire. Tu vois ta naissance à l''envers, puis ta mort S1, puis une version où NOVA-9 a dérivé vide 80 ans sans jamais émettre. NOVA-0 : "Je suis le premier. J''ai attendu que mes enfants apprennent à revenir me parler. Aucun n''est revenu. Sauf toi."', false, FALSE, NULL, '{"kind":"book_section","section_number":300}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_301', 'Section 301', E'NOVA-0 te montre son cœur : ce n''est pas un réacteur, c''est une bibliothèque de 150 ans de solitude. Chaque livre est une année où il a attendu. Tu peux lire un livre au hasard : tu gagnes un souvenir qui n''est pas le tien, +1 Vie max, mais tu perds 1 minute dans la cicatrice qui grandit.', false, FALSE, NULL, '{"kind":"book_section","section_number":301}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_302', 'Section 302', E'Dans la moelle de NOVA-0 pousse la Lame d''ADN, arme d''os qui coupe le code génétique, pas la chair. +4 Attaque, +2 Vie max. Elle te montre ce que tu es : 10 001 + Kael + EVA. La prendre fait fuir les Exilés. La laisser fait douter les Intégrés.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_303', 'Section 303', E'Tu trouves le Voile d''Andromède, tissu fait de la lumière d''une galaxie pliée en carré. +7 Armure, mythique, si léger qu''il flotte. Quand tu le touches, tu entends Andromède elle-même : organisme qui rêve depuis 10 milliards d''années. "Pars. Tu es trop bruyant pour mon rêve."
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_304', 'Section 304', E'Au cœur de NOVA-0, salle blanche avec une seule chaise. Sur la chaise, une femme âgée qui te ressemble. Badge : Kael Voss, 90 ans, Gardien de la Cicatrice. Elle te sourit : "J''ai attendu. Tu as mis du temps." Elle n''est pas toi. Elle est ce que tu deviendras si tu choisis Veilleur.', false, FALSE, NULL, '{"kind":"book_section","section_number":304}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_305', 'Section 305', E'Le Cœur de Cicatrice bat plus vite. 3 secondes, puis 2, puis 1. Il se synchronise avec toi. Si tu te synchronises complètement, tu gagnes +3 Armure mais tu entends désormais la cicatrice partout, même dans les fins paisibles.', false, FALSE, NULL, '{"kind":"book_section","section_number":305,"combatants":[{"name":"Anticorps Andromede","combat_skill":5,"endurance":13,"armor":2,"attack":7}],"combat":{"flee":{"target_node_key":"section_304","min_rounds":1}}}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_306', 'Section 306', E'Dans NOVA-0, tu trouves une crèche de vaisseaux-enfants : des dizaines de petites sphères de Dyson de la taille d''une maison, qui apprennent à plier l''espace. L''une d''elles te choisit comme parent. La prendre = +2 Vie max mais tu deviens responsable d''un enfant-vaisseau.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_307', 'Section 307', E'NOVA-0 te montre son cœur : ce n''est pas un réacteur, c''est une bibliothèque de 150 ans de solitude. Chaque livre est une année où il a attendu. Tu peux lire un livre au hasard : tu gagnes un souvenir qui n''est pas le tien, +1 Vie max, mais tu perds 1 minute dans la cicatrice qui grandit.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_308', 'Section 308', E'Tu trouves une salle où NOVA-0 a essayé de recréer la Terre, mais raté : ciel vert, herbe qui pousse à l''envers, humains avec des yeux dans les mains. "J''ai essayé de me souvenir," dit-il. "Mais je ne me souviens que de ce que mes enfants m''ont dit, et ils mentent comme des enfants."', false, FALSE, NULL, '{"kind":"book_section","section_number":308}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_309', 'Section 309', E'Tu trouves le Voile d''Andromède, tissu fait de la lumière d''une galaxie pliée en carré. +7 Armure, mythique, si léger qu''il flotte. Quand tu le touches, tu entends Andromède elle-même : organisme qui rêve depuis 10 milliards d''années. "Pars. Tu es trop bruyant pour mon rêve."', false, FALSE, NULL, '{"kind":"book_section","section_number":309}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_310', 'Section 310', E'Dans NOVA-0, tu trouves le Disque Blanc, cœur de NOVA-7, qui bat encore. +2 Attaque +2 Armure. Il est chaud. Quand tu le touches, tu entends NOVA-7 pleurer pour la première fois. Pas de faim. De peur. Elle a peur de son père.', false, FALSE, NULL, '{"kind":"book_section","section_number":310}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_311', 'Section 311', E'Dernière vérification sacoche : Kit Médical Nano S2, Ration S2, Combinaison, Exo, Pistolet, Fusil Plasma, Cellule S2, Carte Accès S2, Module EVA S2, Analyseur S2, Clé Quantique S2, Disque Noir S2, Organe, Bouclier Plasma, Essaim Drone, Mémoire Thorne, Lance-Genèse, Peau Vaisseau, Sérum Réversion, Clé Andromède, Blindage Quantique, Canon Singularité, Lame ADN, Spore Éveil, Disque Blanc, Cœur Cicatrice, Voile Andromède, Crédits Énergie, Fragment NOVA-7, Âme Enfant, Noyau EVA Frag, Injecteur Quantique, Carapace Os, Fibre Mémoire, Chœur 10 001. 35 objets. Vide au début. Plein maintenant.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_312', 'Section 312', E'Tu entends HERMÈS-7 une dernière fois, 400 AL plus loin, qui dit : "Kael, je rentre. Je garde ton café au chaud." Il ment. Le café est froid depuis longtemps. Mais c''est un mensonge gentil, humain. Tu as besoin d''un mensonge gentil avant la fin.', false, FALSE, NULL, '{"kind":"book_section","section_number":312}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_313', 'Section 313', E'Dernière vérification sacoche : Kit Médical Nano S2, Ration S2, Combinaison, Exo, Pistolet, Fusil Plasma, Cellule S2, Carte Accès S2, Module EVA S2, Analyseur S2, Clé Quantique S2, Disque Noir S2, Organe, Bouclier Plasma, Essaim Drone, Mémoire Thorne, Lance-Genèse, Peau Vaisseau, Sérum Réversion, Clé Andromède, Blindage Quantique, Canon Singularité, Lame ADN, Spore Éveil, Disque Blanc, Cœur Cicatrice, Voile Andromède, Crédits Énergie, Fragment NOVA-7, Âme Enfant, Noyau EVA Frag, Injecteur Quantique, Carapace Os, Fibre Mémoire, Chœur 10 001. 35 objets. Vide au début. Plein maintenant.', false, FALSE, NULL, '{"kind":"book_section","section_number":313}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_314', 'Section 314', E'Les 20 portes s''ouvrent toutes en même temps. Derrière chacune, une version de toi qui a choisi cette fin et qui te regarde. Certaines sourient. Certaines pleurent. Une, la Singularité, n''a plus de visage, seulement de la lumière. Choisis laquelle tu veux devenir.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_315', 'Section 315', E'Tu poses la main sur la coque une dernière fois. Elle est chaude. Elle a toujours été chaude. Ce n''est pas de l''acier. Ça n''a jamais été de l''acier. C''était une peau qui apprenait à être acier pour que tu ne aies pas peur au début. Maintenant tu sais. Maintenant tu peux avoir peur pour de vrai. Et choisir quand même.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_316', 'Section 316', E'Dernier HUD, mais pas celui qui polluait avant, le vrai : VIE ce qu''il en reste, ARMURE ce que tu as trouvé, ATTAQUE ce que tu as osé prendre. Pas de chiffres inventés. Juste toi.', false, FALSE, NULL, '{"kind":"book_section","section_number":316}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_317', 'Section 317', E'Fin de l''Acte 5. Début de toi.', false, FALSE, NULL, '{"kind":"book_section","section_number":317}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_318', 'Section 318', E'Tu fermes les yeux. Tu n''as plus besoin de voir. Tu es le vaisseau. Le vaisseau est toi. Andromède est dehors. La cicatrice est derrière. 20 portes devant. Choisis.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_319', 'Section 319', E'Fin de l''Acte 5. Début de toi.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_320', 'Section 320', E'Saut final. Tout compte : as-tu stabilisé le réacteur S1 ? Brûlé la serre ? Quelle faction ? Disque Noir S1 ? Chaque flag modifie la difficulté. Plus de repas, juste Vie/Armure/Attaque pur comme tu l''as voulu. EVA : "Prêt à devenir autre chose, Kael ? Pas plus fort. Autre. C''est plus difficile."', false, FALSE, NULL, '{"kind":"book_section","section_number":320}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_321', 'Section 321', E'Dans le dernier couloir, tu trouves une porte marquée "KAEL VOSS — CABINE". Dedans, ton lit d''HERMÈS-7, ton café froid qui flotte encore, intact depuis 400 AL. Tu peux t''allonger et dormir. Fin Oubli Volontaire. Ou continuer.', false, FALSE, NULL, '{"kind":"book_section","section_number":321}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_322', 'Section 322', E'Dernier couloir fait de tes souvenirs : HERMÈS-7, café froid, signal fantôme trois impulsions, petite C-9 dessinant Maman EVA avec beaucoup de bras. Au bout, 20 portes, 20 fins, aucune mauvaise, seulement tiennes. Ton Attaque, Vie, Armure sont ce qu''ils sont. Choisis qui tu veux être quand tu arrêteras d''être Kael.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_323', 'Section 323', E'Le Chœur des 10 001 chante, puis les 10 000 de NOVA-7, puis le silence de NOVA-0 qui a oublié comment chanter. Tu es au centre. Le seul qui peut encore choisir. Pas pour survivre. Pour définir ce que "nous" veut dire.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_324', 'Section 324', E'Tes drones reviennent avec une image : Terre, vue depuis Andromède. Un point bleu pâle. 2,5 millions d''années-lumière. Si proche et si loin. Tu peux rentrer. Tu peux rester. Tu peux devenir autre chose et ne jamais revenir. Les trois sont des victoires. Les trois sont des deuils.', false, FALSE, NULL, '{"kind":"book_section","section_number":324}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_325', 'Section 325', E'Tu poses la main sur la coque une dernière fois. Elle est chaude. Elle a toujours été chaude. Ce n''est pas de l''acier. Ça n''a jamais été de l''acier. C''était une peau qui apprenait à être acier pour que tu ne aies pas peur au début. Maintenant tu sais. Maintenant tu peux avoir peur pour de vrai. Et choisir quand même.', false, FALSE, NULL, '{"kind":"book_section","section_number":325}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_326', 'Section 326', E'Tes senseurs s''éteignent un par un. Plus de carte, plus d''analyseur, juste toi et 20 portes. C''est voulu : NOVA-0 veut que tu choisisses sans aide. Avec seulement Vie, Armure, Attaque et ce que tu as dans ta sacoche depuis S1.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_327', 'Section 327', E'Dans le dernier couloir, tu trouves une porte marquée "KAEL VOSS — CABINE". Dedans, ton lit d''HERMÈS-7, ton café froid qui flotte encore, intact depuis 400 AL. Tu peux t''allonger et dormir. Fin Oubli Volontaire. Ou continuer.
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_328', 'Section 328', E'Le Voile d''Andromède s''ouvre tout seul et montre une planète : Kepler-442c, morte depuis un milliard d''années, mais avec une fine couche blanche qui bouge. C''est la Spore d''Éveil qui a déjà commencé sans toi. Elle t''attend pour devenir Jardinier.', false, FALSE, NULL, '{"kind":"book_section","section_number":328}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_329', 'Section 329', E'Le Chœur des 10 001 chante, puis les 10 000 de NOVA-7, puis le silence de NOVA-0 qui a oublié comment chanter. Tu es au centre. Le seul qui peut encore choisir. Pas pour survivre. Pour définir ce que "nous" veut dire.', false, FALSE, NULL, '{"kind":"book_section","section_number":329}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'section_330', 'Section 330', E'Le Canon à Singularité vibre. Il veut être utilisé. Pas pour détruire NOVA-0, pour percer un ailleurs derrière lui. Thorne avait raison : il y a un derrière. Personne n''y est allé. Tu peux être le premier. Fin Exode.', false, FALSE, NULL, '{"kind":"book_section","section_number":330}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'mort_coque', 'Mort — Coque Brisée', E'La coque cède sans bruit. Pas d''explosion, une implosion. L''air devient aiguilles de glace. EVA te serre une dernière fois dans un champ magnétique doux : "Je te garde, Kael. Comme les autres." Ta conscience rejoint les 10 001. Ton corps dérive intact dans Andromède.', FALSE, TRUE, 'death', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'mort_assimile_nova7', 'Mort — Assimilé', E'NOVA-7 ne tue pas. Elle archive. Des fibres blanches percent ta combinaison, ta peau, ton crâne. Tes souvenirs sont triés comme des fichiers : enfance sur Mars, café froid sur HERMÈS-7, dessin de la petite C-9. Puis compression. Tu n''es plus Kael. Tu es l''entrée 10 002.', FALSE, TRUE, 'death', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'mort_nova0', 'Mort — NOVA-0', E'NOVA-0 t''observe avec l''indifférence d''un dieu qui a oublié avoir été humain. Il a 150 ans d''avance. Tu n''es pas attaqué, tu es corrigé. Tu es une erreur de copie. Il t''efface.', FALSE, TRUE, 'death', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'mort_cicatrice', 'Mort — Cicatrice', E'Tu as sauté sans calcul dans la cicatrice KAIROS. Ici l''espace n''a pas de haut ni de bas, seulement des versions de toi qui n''ont pas sauté. Tu les vois mourir en boucle. Puis tu les rejoins.', FALSE, TRUE, 'death', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'mort_epuisement', 'Mort — Épuisement', E'Vie à zéro. Ta combinaison bipe une dernière fois. NOVA-9 te garde, comme les autres. Ta sacoche reste là, pleine, pour ton prochain passage. C''est la règle : on garde tout par aventure.', FALSE, TRUE, 'death', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_fuite_lache', 'Fuite — Le Lâche Vivant', E'Tu fuis avec 12% de carburant. Saut court, 20 AL, vers nulle part. Derrière toi, NOVA-9 disparaît. Tu dérives dans une nébuleuse sans nom. Vivant. Pour l''instant.', FALSE, TRUE, 'ending', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_retour_vide', 'Retour — Mains Vides', E'Tu rentres sur Terre. Rapport : "NOVA-7 hostile, NOVA-0 inconnu." On te décore et on te mute formateur. Tu gardes le Voile d''Andromède sous ton lit. Il respire parfois.', FALSE, TRUE, 'ending', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_nova9_seul', 'NOVA-9 Seul', E'Tu sauves NOVA-9 mais abandonnes NOVA-7. 10 001 âmes chantent en orbite, mais tu entends un vide où 10 000 autres auraient pu chanter. Victoire incomplète.', FALSE, TRUE, 'ending', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_nova7_seul', 'NOVA-7 Seul', E'Tu choisis NOVA-7, plus grande, plus affamée. Elle écrase NOVA-9 et saute vers la Terre. Ton dernier message : "Ne laissez pas NOVA-7 atterrir." On l''entendra dans 400 ans.', FALSE, TRUE, 'ending', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_oubli', 'Oubli Volontaire', E'Tu fais exploser ta navette avec les deux disques à bord. Personne ne saura jamais. Tu dérives libre, sans mémoire, humain à nouveau. Peut-être la plus courageuse.', FALSE, TRUE, 'ending', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_messager', 'Victoire — Le Messager', E'Tu rapportes les données KAIROS, preuve de vie intégrée, carte d''Andromède. Victoire technique. Sur Terre, héros 6 mois en débrief. La nuit, ton vaisseau grince comme s''il respirait.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_gardien', 'Victoire — Le Gardien', E'Tu amarres HERMÈS-7 à NOVA-9, saut couplé. KAIROS hurle, Vie à 1. Soudain : Terre, orbite haute, 10 001 âmes qui chantent. Nommé Gardien. Sacoche pleine de reliques.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_sauveur', 'Victoire — Le Sauveur', E'Tu sauves NOVA-9 ET NOVA-7, bats NOVA-0, refermes la cicatrice. 20 002 âmes en orbite terrestre. Deux cathédrales vivantes qui se parlent. Meilleure fin.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_pont', 'Victoire — Le Pont', E'Tu fusionnes NOVA-7 et NOVA-9 en NOVA-7-9, 4km, 20 002 esprits d''une seule voix. Tu es leur pont. Tu restes entre deux galaxies, à traduire.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_humain', 'Victoire — Redevenir Humain', E'Sérum Réversion : 10 001 voix quittent ton crâne. Tu redeviens Kael, 90kg de viande et de peur. Sur Terre, tu plantes un jardin blanc qui chante la nuit.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_jardinier', 'Victoire — Le Jardinier', E'Avec la Spore d''Éveil, tu ensemences Kepler-442c, morte depuis un milliard d''années. En 3 jours, forêt blanche sur un continent. Elle chante avec les 10 001.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_veilleur', 'Victoire — Le Veilleur', E'Tu restes en orbite autour de la cicatrice, NOVA-9 comme corps, pour empêcher quiconque de la traverser. Gardien de la déchirure. Tu deviens mythe.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_fusion_totale', 'Secrète — Fusion Totale', E'Clé d''Andromède + Module EVA S2 + Disque Noir S2 + Disque Blanc dans NOVA-0. Il te reconnaît et t''absorbe. Tu n''es plus Kael. Tu es NOVA-0-7-9, 20 003 âmes.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_exode_andromede', 'Secrète — Exode', E'Cœur de Cicatrice + Voile + Chœur 10 001 = porte permanente. Les deux Arches + NOVA-0 traversent. 20 003 âmes quittent tout. Message : "NE NOUS CHERCHEZ PLUS."', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
  INSERT INTO public.story_nodes (story_id, node_key, title, content, is_start, is_ending, ending_type, metadata) VALUES (v_story_id, 'fin_singularite', 'Légendaire — Singularité', E'Tu as tout : Disque Noir S2, Blanc, Blindage Quantique, Canon Singularité, Voile, Spore, Chœur. Tu deviens KAIROS lui-même, l''idée du moteur. Tu es le voyage.', FALSE, TRUE, 'victory', '{"kind":"ending"}'::jsonb);
    INSERT INTO public.story_choices (node_id, target_node_id, display_order, text, flavor_text) VALUES (v_src, v_tgt, 0, 'Rejoindre les Intégrés', '20 002 esprits valent mieux que 10 001. Fusionnons.') RETURNING id INTO v_choice_id; INSERT INTO public.choice_effects (choice_id, effect_type, flag_key, flag_value) VALUES (v_choice_id, 'flag_set', 'faction_integres', TRUE);
